def triangle_and_points(x1, y1, x2, y2, x3, y3, xp, yp, xq, yq) -> int:
    def cross(ax, ay, bx, by, cx, cy):
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)

    if cross(x1, y1, x2, y2, x3, y3) == 0:
        return 1

    def inside(px, py):
        d = (cross(x1, y1, x2, y2, px, py),
             cross(x2, y2, x3, y3, px, py),
             cross(x3, y3, x1, y1, px, py))
        return not (min(d) < 0 < max(d))

    p_in, q_in = inside(xp, yp), inside(xq, yq)
    if p_in and q_in:
        return 2
    if p_in:
        return 3
    if q_in:
        return 4
    return 5
